-- LOCAL PRO ONLY. Copy a fixed company-library version into a saved private daily log.
-- No old function/column replacement, notifications, grants, publication or deletes.
begin;
create table if not exists public.pro_company_daily_log_file_actions(owner_id uuid not null references profiles(id) on delete cascade,action_id uuid not null,actor_name text not null check(length(actor_name)<=160),work_id text not null,log_id uuid not null,source_file_id uuid not null,source_revision integer not null check(source_revision>0),target_file_id uuid not null unique,input jsonb not null,input_hash text not null check(input_hash~'^[a-f0-9]{64}$'),source_snapshot jsonb not null,source_path text not null,internal_input jsonb not null,result jsonb,reserved_at timestamptz not null default now(),primary key(owner_id,action_id),foreign key(owner_id,work_id,log_id,target_file_id) references pro_daily_log_files(owner_id,work_id,log_id,id) on delete cascade,check(source_file_id<>target_file_id));
create or replace function public.pro_company_daily_log_file_auth(p_actor uuid,p_action uuid) returns void language plpgsql security invoker set search_path=public,pg_temp as $$declare r pro_company_daily_log_file_actions;begin
 select * into r from pro_company_daily_log_file_actions where owner_id=p_actor and action_id=p_action;if not found then raise exception 'Copy reservation unavailable' using errcode='42501';end if;
 perform pro_daily_log_file_context(p_actor,r.work_id,r.log_id,null,true,null,true);
 perform pro_daily_file_retirement_guard(p_actor,p_action,r.target_file_id);
 if not exists(select 1 from pro_company_files where owner_id=p_actor and id=r.source_file_id and ready) then raise exception 'Company file access unavailable' using errcode='42501';end if;
 -- Current Pro/profile/log rights are mandatory. Metadata changes and archived
 -- source status do not redirect the immutable bytes/name captured at reserve.
end $$;
create or replace function public.pro_company_daily_log_file_read(p_actor uuid,p_action uuid) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare r pro_company_daily_log_file_actions;begin
 if not coalesce(pro_appointment_enabled(p_actor),false) or not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into r from pro_company_daily_log_file_actions where owner_id=p_actor and action_id=p_action;if not found then return jsonb_build_object('receipt',null);end if;perform pro_company_daily_log_file_auth(p_actor,p_action);
 if r.result is null then return jsonb_build_object('receipt',null);end if;return jsonb_build_object('receipt',jsonb_build_object('inputHash',r.input_hash,'source',r.source_snapshot,'result',r.result));end $$;
create or replace function public.pro_company_daily_log_file_pending(p_actor uuid,p_action uuid) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare r pro_company_daily_log_file_actions;target pro_daily_log_files;begin
 perform pro_company_daily_log_file_auth(p_actor,p_action);select * into r from pro_company_daily_log_file_actions where owner_id=p_actor and action_id=p_action;
 select * into target from pro_daily_log_files where owner_id=p_actor and work_id=r.work_id and log_id=r.log_id and id=r.target_file_id;if not found then raise exception 'Target unavailable' using errcode='42501';end if;
 return jsonb_build_object('input',r.input,'inputHash',r.input_hash,'source',r.source_snapshot,'sourcePath',r.source_path,'file',pro_daily_log_file_json(target),'targetPath',target.object_path,'result',r.result);end $$;
create or replace function public.pro_company_daily_log_file_reserve(p_actor uuid,p_input jsonb,p_input_hash text) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare aid uuid;fid uuid;sid uuid;wid text;lid uuid;f pro_company_files;r pro_company_daily_log_file_actions;internal jsonb;ctx jsonb;begin
 if jsonb_typeof(p_input) is distinct from 'object' or(select array_agg(key order by key) from jsonb_object_keys(p_input)key) is distinct from array['action','actionId','logId','sourceFileId','sourceRevision','sourceSha256','targetFileId','workId'] or jsonb_typeof(p_input->'actionId') is distinct from 'string' or jsonb_typeof(p_input->'sourceFileId') is distinct from 'string' or jsonb_typeof(p_input->'targetFileId') is distinct from 'string' or jsonb_typeof(p_input->'logId') is distinct from 'string' or jsonb_typeof(p_input->'workId') is distinct from 'string' or p_input->>'action' is distinct from 'copy_from_company' or not coalesce(p_input_hash~'^[a-f0-9]{64}$',false) or jsonb_typeof(p_input->'sourceRevision') is distinct from 'number' or not coalesce(p_input->>'sourceRevision'~'^[0-9]{1,10}$',false) or(p_input->>'sourceRevision')::numeric not between 1 and 2147483647 or not coalesce(p_input->>'sourceSha256'~'^[a-f0-9]{64}$',false) then raise exception 'Invalid library copy' using errcode='22023';end if;
 aid:=(p_input->>'actionId')::uuid;fid:=(p_input->>'targetFileId')::uuid;sid:=(p_input->>'sourceFileId')::uuid;wid:=p_input->>'workId';lid:=(p_input->>'logId')::uuid;if aid is null or fid is null or sid is null or lid is null or fid=sid then raise exception 'Invalid copy identity' using errcode='22023';end if;
 perform pro_daily_log_file_context(p_actor,wid,lid,null,true,null,true);
 -- Old file-action advisory first; the legacy facades use this exact lock.
 perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-file-action:'||p_actor::text||':'||aid::text,0));
 select * into r from pro_company_daily_log_file_actions where owner_id=p_actor and action_id=aid;if found then perform pro_company_daily_log_file_auth(p_actor,aid);if r.input is distinct from p_input or r.input_hash<>p_input_hash then raise exception 'Copy action reused' using errcode='22023';end if;return pro_company_daily_log_file_pending(p_actor,aid);end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-company-files:'||p_actor::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||p_actor::text||':'||wid,0));
 perform pro_daily_log_file_context(p_actor,wid,lid,null,true,null,true);perform pro_daily_file_retirement_guard(p_actor,aid,fid);
 if exists(select 1 from pro_daily_log_file_actions where actor_id=p_actor and action_id=aid) or exists(select 1 from pro_daily_log_actions where actor_id=p_actor and action_id=aid) or exists(select 1 from pro_company_file_actions where actor_id=p_actor and action_id=aid) then raise exception 'Action identity used' using errcode='40001';end if;
 select * into f from pro_company_files where owner_id=p_actor and id=sid and ready for share;if not found then raise exception 'Company source unavailable' using errcode='42501';end if;
 if f.archived or f.revision<>(p_input->>'sourceRevision')::integer or f.sha256<>p_input->>'sourceSha256' then raise exception 'Company source changed' using errcode='40001';end if;perform pro_company_ancestors(p_actor,f.folder_id);
 internal:=jsonb_build_object('action','upload','actionId',aid,'fileId',fid,'workId',wid,'logId',lid,'grantId',null,'generation',null,'sourceName',f.name,'name',f.name,'mimeType',f.mime_type,'sizeBytes',f.size_bytes,'rawSha256',f.sha256,'sha256',f.sha256);
 perform pro_daily_log_file_reserve_guarded(p_actor,internal,encode(sha256(convert_to(pro_daily_log_duplicate_canonical(internal),'UTF8')),'hex'));
 insert into pro_company_daily_log_file_actions(owner_id,action_id,actor_name,work_id,log_id,source_file_id,source_revision,target_file_id,input,input_hash,source_snapshot,source_path,internal_input) values(p_actor,aid,pro_team_name(p_actor),wid,lid,sid,f.revision,fid,p_input,p_input_hash,pro_company_file_json(f),f.object_path,internal);
 perform pro_company_daily_log_file_auth(p_actor,aid);return pro_company_daily_log_file_pending(p_actor,aid);end $$;
create or replace function public.pro_company_daily_log_file_ready(p_actor uuid,p_action uuid) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare r pro_company_daily_log_file_actions;ack jsonb;answer jsonb;begin
 perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-file-action:'||p_actor::text||':'||p_action::text,0));perform pro_company_daily_log_file_auth(p_actor,p_action);select * into r from pro_company_daily_log_file_actions where owner_id=p_actor and action_id=p_action;
 if r.result is not null then return r.result;end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||p_actor::text||':'||r.work_id,0));perform pro_company_daily_log_file_auth(p_actor,p_action);
 ack:=pro_daily_log_file_ready_guarded(p_actor,p_action);perform pro_company_daily_log_file_auth(p_actor,p_action);
 answer:=jsonb_build_object('action','copy_from_company','source',r.source_snapshot,'file',ack->'file','revision',ack->'revision');update pro_company_daily_log_file_actions set result=answer where owner_id=p_actor and action_id=p_action;
 perform pro_company_daily_log_file_auth(p_actor,p_action);return answer;end $$;
-- Guard the HTTP legacy entry points under the same advisory as reservation.
-- Internal bridge uses the existing guarded RPCs and keeps their history intact.
create or replace function public.pro_company_daily_log_file_legacy_guard(p_actor uuid,p_action uuid) returns void language plpgsql security invoker set search_path=public,pg_temp as $$begin
 perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-file-action:'||p_actor::text||':'||p_action::text,0));if exists(select 1 from pro_company_daily_log_file_actions where owner_id=p_actor and action_id=p_action) then raise exception 'Use the company-copy receipt' using errcode='42501';end if;end $$;
create or replace function public.pro_company_daily_log_legacy_reserve(p_actor uuid,p_input jsonb,p_input_hash text) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$begin perform pro_company_daily_log_file_legacy_guard(p_actor,(p_input->>'actionId')::uuid);return pro_daily_log_file_reserve_guarded(p_actor,p_input,p_input_hash);end $$;
create or replace function public.pro_company_daily_log_legacy_pending(p_actor uuid,p_action uuid) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$begin perform pro_company_daily_log_file_legacy_guard(p_actor,p_action);return pro_daily_log_file_pending_guarded(p_actor,p_action);end $$;
create or replace function public.pro_company_daily_log_legacy_ready(p_actor uuid,p_action uuid) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$begin perform pro_company_daily_log_file_legacy_guard(p_actor,p_action);return pro_daily_log_file_ready_guarded(p_actor,p_action);end $$;
create or replace function public.pro_company_daily_log_legacy_read(p_actor uuid,p_action uuid) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$begin perform pro_company_daily_log_file_legacy_guard(p_actor,p_action);return pro_daily_log_file_action_read_guarded(p_actor,p_action);end $$;
create or replace function public.pro_company_daily_log_file_immutable() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$begin if old.result is not null or new.result is null or(to_jsonb(new)-'result') is distinct from(to_jsonb(old)-'result') then raise exception 'Immutable company copy receipt' using errcode='23514';end if;return new;end $$;
drop trigger if exists pro_company_daily_log_file_immutable on public.pro_company_daily_log_file_actions;
create trigger pro_company_daily_log_file_immutable before update on public.pro_company_daily_log_file_actions for each row execute function pro_company_daily_log_file_immutable();
alter table public.pro_company_daily_log_file_actions enable row level security;
revoke all on public.pro_company_daily_log_file_actions from public,anon,authenticated;
grant all on public.pro_company_daily_log_file_actions to service_role;
do $$declare f record;begin for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and(p.proname like 'pro_company_daily_log_file_%' or p.proname like 'pro_company_daily_log_legacy_%') loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to service_role',f.signature);end loop;end $$;
commit;
